    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Притулок від поганого сусіда", "О Аллах, я вдаюся до Тебе від поганого сусіда за місцем постійного проживання, бо сусід у дорозі йде далі.", "Для захисту від поганого сусіда.", "Пророк ﷺ наказав шукати притулку від цього."),
        "dua_ishfi_abdak" to DuaText("Для одужання хворої людини", "О Аллах, вилікуй Твого слугу, щоб він міг протистояти ворогу за Тебе або ходити на молитву за Тебе.", "Для хворого при його відвідуванні.", "Пророк ﷺ навчав говорити це для хворих."),
        "dua_la_mania" to DuaText("Ніхто не може стримати того, що ви даєте", "Ніхто не гідний поклоніння, крім Аллаха, єдиного, без партнера. Його влада і хвала, і Він має владу над усім. О Аллах, ніхто не може утримати те, що Ти даєш, і ніхто не може дати те, що Ти утримуєш, і багатство багатих не має користі проти Тебе.", "Після саляму обов'язкова молитва.", "Пророк ﷺ сказав це після кожної обов'язкової молитви."),
        "dua_slaughtering" to DuaText("При забої тварини", "В ім'я Аллаха, і Аллах найбільший.", "При принесенні в жертву або забої тварини.", "Пророк ﷺ сказав Бісміллах і такбір під час жертвопринесення."),
        "dua_undressing" to DuaText("При знятті одягу", "В ім'я Аллаха.", "При роздяганні (на гуслі чи переодяганні).", "Він стає ширмою між очима джина та інтимними місцями людини."),
        "dua_ilbas_jadidan" to DuaText("Побачити когось у новому одязі", "Носи нове, живи гідно похвали і помри мученицькою смертю.", "Побачивши брата-мусульманина в новому одязі.", "Пророк ﷺ зробив цю дуа, побачивши Умара (RA) у новому одязі."),
        "dua_hajj_la_riya" to DuaText("Хадж без показухи", "О Аллах, (зроби це) хадж без показухи і без пошуку слави.", "За щирість при намірі на хадж.", "Пророк ﷺ зробив цю дуа під час хаджу."),
        "dua_q_muslimayni_laka" to DuaText("Дуа Ібрагіма та Ісмаїла (AS) — Зробіть нас покірними", "Господи наш, зроби нас обох покірними Тобі і з наших нащадків народ, покірний Тобі. Покажи нам наші обряди поклоніння і прийми наше покаяння. Воістину, Ти — Той, хто приймає покаяння, Милосердний.", "Дуа покори собі і своїм нащадкам.", "Дуа зроблена під час будівництва Кааби."),
        "dua_q_iftah_baynana" to DuaText("Дуа Шуайба (AS) — Суддя між нами", "Господи наш, розсуди по правді між нами та нашим народом, і Ти найкращий із суддів.", "Для суду між правдою та брехнею.", "Дуа Шуайба (AS), коли його люди відкинули його."),
        "dua_q_la_akuna_zahiran" to DuaText("Дуа Муси (AS) — Ніколи не помічник злочинців", "Мій Господи, через ласку, яку Ти наділив мене, я ніколи не буду помічником злочинців.", "Подяка за благословення Аллаха і обіцянка не допомагати кривдникам.", "Застава Муси (AS) після його покаяння."),
        "dua_q_nuh_unsurni" to DuaText("Дуа Нуха (AS) — Допоможи мені, вони відмовляють мені", "Мій Господи, допоможи мені, бо вони зреклися мене.", "Коли люди заперечують тебе і відкидають правду.", "Дуа Нуха (AS), на яку було дано відповідь."),
        "dua_q_ihkum_bil_haqq" to DuaText("Мій Господи, суди по правді", "Мій Господи, суди по правді. І наш Господь є Милосердним, Його допомоги шукають проти того, що ви описуєте.", "Перед обличчям брехні та фальшивих звинувачень.", "Дуа, яку навчають Пророку ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Притулок від нищівних боргів і ворогів", "О Аллах, я шукаю притулку в Тебе від того, щоб бути пригніченим боргами, від перемоги ворогом і від злорадства ворогів.", "Захист від тягаря боргів і панування ворогів.", "Пророк ﷺ шукав притулку від цих речей."),
        "dua_faqr_qillah_dhillah" to DuaText("Притулок від бідності та приниження", "О Аллах, я шукаю притулку в Тебе від бідності, нестачі та приниження, а також від того, щоб заподіяти несправедливість іншим або бути несправедливим.", "Щоб захиститися від труднощів, злиднів і принижень.", "Притулок, якому навчав Пророк ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Прости, помилуй, направляй, зцілюй, забезпечуй", "О Аллах, прости мене, помилуй мене, настав мене, даруй мені благополуччя і забезпечи мене.", "Пророк ﷺ навчив цю дуа разом із молитвою нових мусульман.", "Пророк ﷺ сказав: ці слова збирають для вас цей світ і потойбіччя."),
        "dua_ruku_laka_raka_tu" to DuaText("В Руку — Тобі я вклонився", "О Аллах, Тобі я вклонився, у Тебе я увірував і Тобі я підкорився. Слух мій, зір мій, розум мій, кістки мої та сухожилля мої смирені перед Тобою.", "У руку (особливо в добровільних молитвах).", "Пророк ﷺ прочитав це на руку."),
        "dua_sujood_laka_sajadtu" to DuaText("In Sudjood — Тобі я поклонився", "О Аллах, Тобі я поклонився, у Тебе я увірував і Тобі я підкорився. Обличчя моє вклонилося Тому, Хто створив його, сформував і породив його слух і зір. Благословенний Аллах, найкращий із творців.", "У суджуді (особливо в добровільних молитвах).", "Пророк ﷺ прочитав це в суджуді."),
        "dua_ruku_sujood_subhanaka" to DuaText("Слава Тобі, Господи наш — Прости мене", "Слава Тобі, о Аллах, Господь наш, і хвала Тобі. О Аллах, прости мене.", "У руку і суджуд.", "Айша (RA): Пророк ﷺ часто говорив це на руку та суджуд."),
        "dua_q_musa_li_akhi" to DuaText("Дуа Муси (AS) — Прости мене та мого брата", "Мій Господи, прости мене і мого брата і впусти нас у Твоє милосердя, бо Ти — Наймилосердніший із милосердних.", "Прощення собі та братові чи близьким.", "Дуа Муси (AS) для Харуна (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Я довіряю свою справу Аллаху", "І я довіряю свою справу Аллаху. Воістину, Аллах всебачить Своїх рабів.", "Коли люди виступають проти вас, і справу потрібно залишити Аллаху.", "Слова віруючого з народу фараона; Тоді Аллах захистив його від їхніх злих задумів."),
        "dua_q_hawariyyun" to DuaText("Дуа учнів — запишіть нас зі свідками", "Господи наш, ми повірили в те, що Ти відкрив, і ми пішли за Посланцем, тож запиши нас серед свідків.", "За стійкість у вірі та в слідуванні Посланцю.", "Дуа учнів Ісаї (AS)."),
        "dua_q_la_tukhzini" to DuaText("Дуа Ібрагіма (AS) — Не ганьби мене", "І не ганьби мене в той день, коли вони воскреснуть.", "Щоб врятуватися від ганьби в День Воскресіння.", "Дуа Ібрагіма (AS) для потойбіччя."),
        "dua_iftar_laka_sumtu" to DuaText("Іфтар — для вас я постився", "О Аллах, заради Тебе я постив і з Твоїм забезпеченням я розговляюся.", "Під час розговлення (відомий іфтар дуа).", "Пророк ﷺ сказав це під час іфтару. Це мурсальна розповідь, посилена іншими нараціями; читати його під час іфтару є практикою ханафітів і більшості."),
        "dua_iftar_ibn_umar" to DuaText("Іфтар — з Твого великого милосердя, прости мене", "О Аллах, я прошу Тебе через Твою милість, яка охоплює все, прости мені.", "Під час іфтару — Абдулла ібн Амр (RA) зробив цю дуа; дуа постника під час іфтару не відкидається.", "Хадис: дуа постника під час іфтара не відкидається."),
        "dua_inni_saim" to DuaText("При провокації під час голодування", "Я постю, я постю.", "Коли під час посту хтось ображає або свариться з тобою.", "Пророк ﷺ сказав: піст - це щит, тому постуючий не повинен говорити непристойно або діяти неосвічено - якщо хтось свариться, скажи це двічі."),
        "dua_eid_takbeer" to DuaText("Такбір на шляху до Іду", "Аллах є найбільшим, Аллах є найбільшим, немає бога, крім Аллаха, і Аллах є найбільшим, Аллах є найбільшим, і вся хвала Аллаху.", "Від ночі побачення місяця до молитви Ід аль-Фітр, особливо по дорозі до землі Ід.", "Наказ Корану: «щоб ви завершили підрахунок і проголосили велич Аллаха» (аль-Бакара 2:185). Ібн Масуд (RA) сказав цей такбір."),
        "dua_ahsin_aqibatana" to DuaText("Зробіть наш кінець добрим у всіх справах", "О Аллах, зроби наш кінець добрим у всіх справах і захисти нас від ганьби в цьому світі і покарання в майбутньому.", "Для гарного результату в кожній справі.", "Той, хто вимовляє цю дуа і помре до суду, помирає (захищений від суду)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Я прошу вашої щедрості та милосердя", "О Аллах, я прошу Тебе про Твою щедрість і Твою милість, бо ніхто не володіє ними, крім Тебе.", "Коли просять забезпечення і милості.", "Гості приходили до Пророка ﷺ, коли не було їжі; він зробив цю дуа, а потім прийшов подарунок."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Слова, яких навчили бедуїни", "Ніхто не гідний поклоніння, крім Аллаха, єдиного, без партнера. Аллах найбільший, великий; велика хвала Аллаху; слава Аллаху, Господу світів; і немає ні могутності, ні влади, крім Аллаха, Всемогутнього, Мудрого.", "Вичерпна фраза зікр і дуа — навчена бедуїну.", "Після цього його навчили говорити «Аллахуммагфір лі вархамні вахдіні варзукні»."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Пробачте те, що я надіслав до і після", "O Allah, forgive me the sins I committed before and after, what I did in secret and what I did openly, my excesses, and what You know better than I do. Ти Той, Хто веде вперед і Той, Хто повертає назад; немає бога, крім Тебе.", "Після ташаххуда і салавата, перед салямом.", "Пророк ﷺ прочитав це в кінці молитви, між ташаххудом і салямом."),
        "dua_jiddi_wa_hazli" to DuaText("Вибачте за мою серйозність і жарти", "О Аллах, прости мені гріхи, які я вчинив серйозно і жартома, помилково і навмисно — і все це в мені.", "Прощення всякого роду гріхів, відомих і невідомих.", "Повний істігфар Пророка ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Після Руку — Хвала, що наповнює небеса", "Наш Господь, Тобі належить уся хвала, наповнюючи небеса, наповнюючи землю і наповнюючи все, що Ти забажаєш після цього.", "Після підйому з руки разом з «Раббана лакал-хамд».", "Пророк ﷺ сказав це, встаючи з руки."),
        "dua_istiftah_kabira" to DuaText("Аллах найбільший, славний", "Аллах найбільший, великий; велика хвала Аллаху; і слава Аллаху вранці і ввечері.", "На початку молитви (одна з форм вступної хвали).", "Пророк ﷺ сказав: для нього були відкриті ворота раю."),
        "dua_q_ashku_bathhi" to DuaText("Дуа Якуба (AS) — Я скаржуся тільки Аллаху", "Я скаржуся на свою тугу і своє горе тільки Аллаху.", "У глибокій скорботі і розлуці.", "Якуб (AS) сказав це під час розлуки з Юсуфом (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Аллах - найкращий захисник", "Аллах – найкращий Захисник, і Він – Милосердний із милосердних.", "Відправляючи в дорогу дітей або близьких.", "Якуб (AS) сказав це, довіряючи свого сина Аллаху."),
        "dua_q_aqraba_rashada" to DuaText("Нехай мій Господь наведе мене ближче до правди", "Можливо, мій Господь направить мене до того, що є ближчим до правильної поведінки.", "У пошуках кращого шляху в якійсь справі.", "Пророку ﷺ було сказано сказати це після забуття."),
        "dua_q_sawa_as_sabil" to DuaText("Дуа Муси (AS) — Веди мене на правильний шлях", "Можливо, мій Господь направить мене на правильний шлях.", "Вирушаючи в нову подорож або незнайому дорогу.", "Муса (AS) сказав це, повертаючись до Мадяна."),
        "dua_q_not_among_wrongdoers" to DuaText("Не ставте мене до грішників", "Мій Господи, не відноси мене до грішників.", "Дуа з проханням до Аллаха тримати людей окремо від злочинців.", "Дуа з проханням до Аллаха тримати людей окремо від злочинців."),
        "dua_q_do_not_make_us_trial" to DuaText("Не робіть нас випробуванням", "Господи наш, не роби нас випробуванням для невіруючих і прости нас, Господи наш. Воістину, Ти Всемогутній, Мудрий.", "Дуа Ібрагіма (AS) і його сподвижників.", "Дуа Ібрагіма (AS) і його сподвижників."),
        "dua_morning_witness" to DuaText("Ранковий свідок Таухід", "О Аллах, я увійшов у ранок, закликаючи Тебе, носіїв Твого Престолу, Твоїх ангелів і все Твоє творіння, щоб засвідчити, що Ти — Аллах, немає бога, крім Тебе, Самотнього, без партнера, і що Мухаммад ﷺ — Твій слуга і Посланник.", "У переказі згадується промовлення цього чотири рази вранці.", "У переказі згадується промовлення цього чотири рази вранці."),
